CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, phone text UNIQUE NOT NULL, name text NOT NULL DEFAULT '', role text NOT NULL DEFAULT 'owner', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token text PRIMARY KEY, user_id text REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS otp_challenges (id text PRIMARY KEY, session_token text NOT NULL REFERENCES sessions(token), phone text NOT NULL, code_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), consumed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS providers (id text PRIMARY KEY, user_id text UNIQUE REFERENCES users(id), name text NOT NULL, service text NOT NULL, bio text NOT NULL, license text NOT NULL DEFAULT '', verified boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT false, species text[] NOT NULL DEFAULT ARRAY['cat','dog'], areas text[] NOT NULL DEFAULT ARRAY['saadat','shahrak','vanak','yousef','niavaran'], price bigint NOT NULL, avatar text NOT NULL DEFAULT 'vet', experience integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS availability (id text PRIMARY KEY, provider_id text NOT NULL REFERENCES providers(id), day date NOT NULL, period text NOT NULL, capacity integer NOT NULL DEFAULT 2, UNIQUE(provider_id,day,period));
CREATE TABLE IF NOT EXISTS pets (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), name text NOT NULL, species text NOT NULL, age text NOT NULL DEFAULT '', weight text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS bookings (id text PRIMARY KEY, session_token text NOT NULL REFERENCES sessions(token), owner_id text REFERENCES users(id), service text NOT NULL, stage integer NOT NULL DEFAULT 1, pet_name text NOT NULL DEFAULT '', species text NOT NULL DEFAULT 'cat', age text NOT NULL DEFAULT '', weight text NOT NULL DEFAULT '', answers jsonb NOT NULL DEFAULT '{}', area text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', provider_id text REFERENCES providers(id), availability_id text REFERENCES availability(id), items text[] NOT NULL DEFAULT '{}', sample text NOT NULL DEFAULT '', consent boolean NOT NULL DEFAULT false, amount bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft', payment_status text NOT NULL DEFAULT 'unpaid', payment_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz, exact_time timestamptz, meeting_url text NOT NULL DEFAULT '', prescription text NOT NULL DEFAULT '', result text NOT NULL DEFAULT '', replacement_id text REFERENCES providers(id), refund_amount bigint NOT NULL DEFAULT 0, refund_reason text NOT NULL DEFAULT '', refund_status text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS booking_events (id bigserial PRIMARY KEY, booking_id text NOT NULL REFERENCES bookings(id), actor_id text REFERENCES users(id), event text NOT NULL, detail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id bigserial PRIMARY KEY, booking_id text REFERENCES bookings(id), user_id text REFERENCES users(id), kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', dedup_key text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'local', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS applications (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), service text NOT NULL, name text NOT NULL, license text NOT NULL DEFAULT '', bio text NOT NULL, area text NOT NULL DEFAULT '', price bigint NOT NULL, status text NOT NULL DEFAULT 'pending', reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), subject text NOT NULL, body text NOT NULL, reply text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (booking_id text PRIMARY KEY REFERENCES bookings(id), user_id text NOT NULL REFERENCES users(id), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS bookings_owner ON bookings(owner_id,created_at);
CREATE INDEX IF NOT EXISTS bookings_queue ON bookings(status,paid_at);
CREATE INDEX IF NOT EXISTS otp_rate ON otp_challenges(phone,created_at);
